const ServiceCard = ({ imgUrl, titulo, descripcion }) =&gt; {

  const irAFormulario = () =&gt; {
    // Lógica para pre-llenar el formulario
    window.location.href = `/contacto?servicio=${titulo}`;
  };

  return (
    &lt;article className="card-container"&gt;
      &lt;img src={imgUrl} alt={`Imagen representativa de ${titulo}`} /&gt;
      &lt;div className="card-body"&gt;
        &lt;h3&gt;{titulo}&lt;/h3&gt;
        &lt;p&gt;{descripcion}&lt;/p&gt;
        &lt;button onClick={irAFormulario} className="btn-primary"&gt;
          Contáctanos
        &lt;/button&gt;
      &lt;/div&gt;
    &lt;/article&gt;
  );
};
export default ServiceCard;

